17	
18	let lastAssistant = "";
19	try {
20	  const lines = fs.readFileSync(ev.transcript_path, "utf8").split("\n").filter(Boolean);
21	  for (let i = lines.length - 1; i >= 0; i--) {
22	    const m = JSON.parse(lines[i]);
23	    if (m?.message?.role === "assistant") {
24	      lastAssistant = (m.message.content || []).filter((c) => c.type === "text").map((c) => c.text).join("\n");
