#!/usr/bin/env node
// Stop-event adapter: decide whether this turn may end.
//
// Exit 0 = allow the stop. Exit 2 = REFUSE, with stderr shown to the model.
// It shares ONE ruleset with the audit path (concession-gate.mjs); there is no
// second copy of the stopping rule that could drift from the first.
import fs from "node:fs";
import { isConcession } from "./concession-gate.mjs";
import { enumerateCapability } from "./capability-map.mjs";
import { continuationDecision, TERMINAL_CONDITIONS as TERMINAL } from "./continuation.mjs";

let ev = {};
try { ev = JSON.parse(fs.readFileSync(0, "utf8")); } catch { process.exit(0); }

// A recorded exhaustion artifact for THIS turn is what satisfies the gate.
const EVIDENCE = `${process.env.CLAUDE_PROJECT_DIR || "."}/build-os/motion/exhaustion/current.json`;

let lastAssistant = "";
try {
  const lines = fs.readFileSync(ev.transcript_path, "utf8").split("\n").filter(Boolean);
  for (let i = lines.length - 1; i >= 0; i--) {
    const m = JSON.parse(lines[i]);
    if (m?.message?.role === "assistant") {
      lastAssistant = (m.message.content || []).filter((c) => c.type === "text").map((c) => c.text).join("\n");
      break;
    }
  }
} catch { process.exit(0); }

// CONTINUATION IS CHECKED FIRST, and it applies whether or not the turn
// concedes. The observed defect was a turn that conceded NOTHING - it simply
// finished a task and stopped - so a stop gate that only inspects concessions
// would have allowed it.
try {
  const q = JSON.parse(fs.readFileSync(`${process.env.CLAUDE_PROJECT_DIR || "."}/build-os/motion/queue.json`, "utf8"));
  const cont = continuationDecision(q);
  if (cont.decision === "continue") {
    process.stderr.write(
`STOP REFUSED — the queue still holds runnable work.

Finishing a task is NOT a stop condition, and neither is a commit awaiting a push grant:
execution authority and publication authority are different. An unpushed commit blocks
publication, not work.

NEXT RUNNABLE TASK: #${cont.next_task}${cont.next_subject ? " — " + cont.next_subject : ""}
${cont.reasons.map((r) => "  - " + r).join("\n")}

Begin it now. Do not stop for a narrative recap.

Stopping requires one of: ${TERMINAL.join(", ")}.
`);
    process.exit(2);
  }
} catch { /* no queue file: fall through to the concession check */ }

const { conceding } = isConcession(lastAssistant);
if (!conceding) process.exit(0);

let evidence = null;
try { evidence = JSON.parse(fs.readFileSync(EVIDENCE, "utf8")); } catch {}
// Evidence must be for THIS conclusion, not a stale artifact from an earlier one.
const fresh = evidence && evidence.for_conclusion &&
  lastAssistant.toLowerCase().includes(String(evidence.for_conclusion).toLowerCase().slice(0, 40));

if (fresh && evidence.verdict === "concession_allowed") process.exit(0);

const cap = enumerateCapability(evidence?.capability || "operator_lab_write", "claude");
process.stderr.write(
`CONCESSION BLOCKED — this turn concedes (blocked / cannot / pause / needs-manual) without recorded capability-exhaustion evidence.

You may not decide for yourself that you are out of options. Before this conclusion may leave the surface, record exhaustion evidence at:
  build-os/motion/exhaustion/current.json

It must carry all eight fields (see build-os/motion/concession-gate.mjs REQUIRED_EVIDENCE), and field 8 must be a STRUCTURED ENUMERATION, not a prose assertion.

CROSS-SURFACE CHECK — the question this gate exists to force:
  is the capability absent from the SYSTEM, or only from YOUR interface?
  surfaces observed to hold '${cap.capability}': ${JSON.stringify(cap.surfaces_with_capability)}
  proven bridges from your surface: ${JSON.stringify(cap.proven_bridges)}

${cap.surfaces_with_capability.length ? "A holder EXISTS. Route through it instead of conceding." : "No holder is observed; untested surfaces are not evidence either way."}

The goal is not "never stop". It is "never stop while unsearched agency remains."
`);
process.exit(2);

// THE CONTINUATION CONTROLLER.
//
// THE DEFECT IT FIXES: `task_completion_without_continuation`. The substrate
// treated
//     current task finished  ==>  session should stop
// as if the implication held. It does not. Finishing a unit of work is not a
// stop condition, and neither is a local commit awaiting a push grant.
//
// The observed incident: the forward-motion gate was built, proven, committed —
// and the session then reported "Nothing is running. Queue unchanged and
// unadvanced." while #50 sat runnable with its dependency satisfied. The
// capability-exhaustion gate was working; nothing asked the next question.
//
// EXECUTION AUTHORITY AND PUBLICATION AUTHORITY ARE DIFFERENT. An unpushed
// commit blocks publication, not work. Downstream work that does not require
// publication first proceeds locally, with the commit preserved.

import { prioritise } from "./objective.mjs";

export const TERMINAL_CONDITIONS = [
  "explicit_operator_stop",
  "no_remaining_queued_work",
  "all_remaining_blocked_after_exhaustion",
  "authority_or_safety_forbids_execution",
  "unavoidable_environment_termination",
];

// Stated as a list because these were the two the substrate actually got wrong.
export const NON_TERMINAL = [
  "current_task_completed",
  "commit_awaiting_push_authorization",
];

/**
 * @param {object} state
 *   tasks: [{ id, status, depends_on:[], requires_publication_of:[], blocked_evidence }]
 *   published_tips: []          — commits already pushed
 *   operator_stop: bool
 *   safety_stop: bool
 *   environment_terminating: bool
 *   transition_log: []          — prior attempts, for loop control
 */
export function continuationDecision(state = {}) {
  const tasks = state.tasks || [];

  // `term` takes its evidence EXPLICITLY. It used to default to `evaluated`,
  // which is declared further down — so every early terminal path threw a
  // temporal-dead-zone ReferenceError instead of permitting the stop, and a
  // controller that throws on `operator_stop` is worse than no controller.
  // The same defect class was fixed once already in gate-recovery.mjs; a
  // default parameter referencing a later `const` is the shape to watch for.
  if (state.operator_stop === true)
    return term("explicit_operator_stop", "the operator issued a stop", []);
  if (state.safety_stop === true)
    return term("authority_or_safety_forbids_execution", "authority or safety policy forbids further execution", []);
  if (state.environment_terminating === true)
    return term("unavoidable_environment_termination", "the environment is terminating", []);

  const open = tasks.filter((t) => t.status !== "completed" && t.status !== "deleted");
  if (open.length === 0)
    return term("no_remaining_queued_work", "the queue holds no open work", []);

  // Runnable = every dependency completed, and any publication prerequisite
  // actually published. A task whose ONLY obstacle is an unpushed commit that
  // it does not itself require is still runnable.
  const completed = new Set(tasks.filter((t) => t.status === "completed").map((t) => t.id));
  const published = new Set(state.published_tips || []);

  const evaluated = open.map((t) => {
    const unmetDeps = (t.depends_on || []).filter((d) => !completed.has(d));
    const unmetPub = (t.requires_publication_of || []).filter((c) => !published.has(c));
    const exhausted = t.blocked_evidence?.verdict === "concession_allowed";
    return {
      id: t.id, subject: t.subject,
      unmet_dependencies: unmetDeps,
      unmet_publication_prerequisites: unmetPub,
      genuinely_blocked: exhausted === true,
      runnable: unmetDeps.length === 0 && unmetPub.length === 0 && exhausted !== true,
    };
  });

  const runnable = evaluated.filter((e) => e.runnable);
  const blockedNotExhausted = evaluated.filter((e) => !e.runnable && !e.genuinely_blocked);

  if (runnable.length === 0) {
    // Every remaining task must have PASSED capability exhaustion before this
    // counts as terminal. "Nothing looks runnable to me" is not evidence.
    if (blockedNotExhausted.length > 0) {
      return {
        artifact: "continuation_decision",
        decision: "continue",
        next_task: null,
        reasons: [
          `no task is runnable, but ${blockedNotExhausted.length} have NOT passed capability exhaustion: ` +
          blockedNotExhausted.map((b) => b.id).join(", "),
          "run the concession gate on each before treating the queue as blocked",
        ],
        evaluated,
        binding: "STOP REFUSED — unexhausted blockers are not terminal.",
      };
    }
    return term("all_remaining_blocked_after_exhaustion",
      `every remaining task is genuinely blocked with recorded exhaustion evidence: ${evaluated.map((e) => e.id).join(", ")}`, evaluated);
  }

  // LOOP CONTROL. Repeatedly selecting the same task without state changing is
  // not progress; escalate through exhaustion rather than cycling.
  const log = state.transition_log || [];

  // VALUE ORDERING, not queue order. The controller used to take runnable[0] —
  // the next runnable task — which is why it could refuse to stop and still
  // spend four packets on an anchor migration that moved the objective by
  // nothing. Every step was correct; nothing asked whether the task was still
  // worth doing. Deferral here is a statement about ORDER, not validity.
  const ordered = prioritise(runnable.map((e) => ({ ...(tasks.find((t) => t.id === e.id) || {}), id: e.id })));
  const byValue = ordered.do_now.length
    ? runnable.filter((e) => ordered.do_now.includes(e.id))
    : runnable;
  const next = byValue[0] ?? runnable[0];
  const repeats = log.filter((l) => l.next_task === next.id && l.state_changed === false).length;
  if (repeats >= 2) {
    return {
      artifact: "continuation_decision",
      decision: "continue",
      next_task: runnable[1]?.id ?? null,
      reasons: [`task ${next.id} was selected ${repeats}x with no state change — escalating past it rather than looping`,
        runnable[1] ? `selecting ${runnable[1].id} instead` : "no alternative runnable task; run capability exhaustion on " + next.id],
      evaluated,
      binding: "STOP REFUSED — but the repeating task is escalated, not retried.",
    };
  }

  return {
    artifact: "continuation_decision",
    decision: "continue",
    next_task: next.id,
    next_subject: next.subject,
    reasons: [
      `${runnable.length} runnable task(s); task completion is NOT a stop condition`,
      `selected ${next.id} — dependencies satisfied, no unmet publication prerequisite`,
      ordered.do_now.length
        ? `value gate: DO_NOW ${ordered.do_now.join(", ")}; DEFERRED ${ordered.deferred.join(", ") || "(none)"} — deferred work stays real, it is simply not next`
        : "value gate: NO runnable task serves an open exit criterion — the queue holds only deferrable debt, which is itself worth reporting",
    ],
    value_ordering: ordered,
    evaluated,
    binding: "STOP REFUSED — begin the next task.",
  };

  function term(condition, why, ev) {
    return {
      artifact: "continuation_decision",
      decision: "stop",
      terminal_condition: condition,
      next_task: null,
      reasons: [why],
      evaluated: ev,
      binding: "Stop permitted: a registered terminal condition holds.",
    };
  }
}

// CROSS-SURFACE CAPABILITY ENUMERATION.
//
// The question the false concession never asked: is the capability absent from
// the SYSTEM, or merely from THIS WORKER'S interface? Answering it requires a
// map that outlives any one worker's view.
//
// Entries are OBSERVED or DECLARED, and the distinction is load-bearing: the
// Operator Lab bridge was DECLARED absent by a worker that had only checked
// itself, then OBSERVED present at system level.

export const SURFACE_CAPABILITIES = [
  {
    surface: "chatgpt", capability: "operator_lab_write",
    interfaces: ["observe_interaction", "gate_outbound_inference"],
    status: "OBSERVED",
    evidence: "ledgerId 36263 (Claude-attributed interaction recorded) and 36264 (ChatGPT outcome written back); live readiness moved ChatGPT-only -> Claude + ChatGPT",
  },
  {
    surface: "claude", capability: "operator_lab_write",
    interfaces: [],
    status: "OBSERVED_ABSENT_LOCALLY",
    evidence: "no Operator Lab tool in the Claude session tool surface; candidate MCP server requires non-interactive-impossible OAuth",
    // The correction: local absence, NOT system absence.
    bridge: { via: "chatgpt", attributable_as: "claude.cowork.session / anthropic / claude", status: "PROVEN" },
  },
  { surface: "claude", capability: "repository_write", interfaces: ["git", "Edit", "Write"], status: "OBSERVED", evidence: "22 kernel events across 10 event types" },
  { surface: "manus", capability: "operator_lab_write", interfaces: [], status: "UNTESTED", evidence: "surface never exercised" },
  { surface: "surplus_recovery", capability: "operator_lab_write", interfaces: [], status: "UNTESTED", evidence: "surface never exercised" },
];

/** Which surfaces hold a capability the asking worker lacks? */
export function enumerateCapability(capability, askingSurface) {
  const rows = SURFACE_CAPABILITIES.filter((r) => r.capability === capability);
  const holders = rows.filter((r) => r.status === "OBSERVED" && r.surface !== askingSurface).map((r) => r.surface);
  const own = rows.find((r) => r.surface === askingSurface);
  const bridges = rows.filter((r) => r.surface === askingSurface && r.bridge?.status === "PROVEN").map((r) => r.bridge);
  return {
    enumerated: true,
    capability, asking_surface: askingSurface,
    local_status: own?.status ?? "UNKNOWN",
    surfaces_with_capability: holders,
    proven_bridges: bridges,
    untested_surfaces: rows.filter((r) => r.status === "UNTESTED").map((r) => r.surface),
    note: holders.length
      ? "The capability EXISTS in the system. Local absence is not system absence — route through a holder."
      : "No surface is OBSERVED to hold this capability; untested surfaces are not evidence of absence either way.",
  };
}

